describe("sympy/functions/special/tests/test_mathieu.py", () => {
  it("test_mathieus:12", () => {
    const [a, z] = symbols('a z');
    expect(sympyStr(mathieus(a, Rational.of(0n, 1n, { gcd: 1n }), z))).toBe('sin(sqrt(a)*z)');
  });
  it("test_mathieus:13", () => {
    const [a, q, z] = symbols('a q z');
    expect(sympyStr(fn('conjugate', [fn('mathieus', [a, q, z])], { evaluate: true }))).toBe('mathieus(conjugate(a), conjugate(q), conjugate(z))');
  });
  it("test_mathieus:14", () => {
    const [a, q, z] = symbols('a q z');
    expect(sympyStr(diff(fn('mathieus', [a, q, z]), z, 1))).toBe('mathieusprime(a, q, z)');
  });
  it("test_mathieuc:18", () => {
    const [a, z] = symbols('a z');
    expect(sympyStr(mathieuc(a, Rational.of(0n, 1n, { gcd: 1n }), z))).toBe('cos(sqrt(a)*z)');
  });
  it("test_mathieuc:19", () => {
    const [a, q, z] = symbols('a q z');
    expect(sympyStr(diff(fn('mathieuc', [a, q, z]), z, 1))).toBe('mathieucprime(a, q, z)');
  });
  it("test_mathieusprime:23", () => {
    const [a, z] = symbols('a z');
    expect(sympyStr(mathieusprime(a, Rational.of(0n, 1n, { gcd: 1n }), z))).toBe('sqrt(a)*cos(sqrt(a)*z)');
  });
  it("test_mathieusprime:24", () => {
    const [a, q, z] = symbols('a q z');
    expect(sympyStr(diff(fn('mathieusprime', [a, q, z]), z, 1))).toBe('(-a + 2*q*cos(2*z))*mathieus(a, q, z)');
  });
  it("test_mathieucprime:28", () => {
    const [a, z] = symbols('a z');
    expect(sympyStr(mathieucprime(a, Rational.of(0n, 1n, { gcd: 1n }), z))).toBe('-sqrt(a)*sin(sqrt(a)*z)');
  });
  it("test_mathieucprime:29", () => {
    const [a, q, z] = symbols('a q z');
    expect(sympyStr(diff(fn('mathieucprime', [a, q, z]), z, 1))).toBe('(-a + 2*q*cos(2*z))*mathieuc(a, q, z)');
  });
});

